WITH flattened_attrs AS (SELECT id, log_ts, level, latency_ms, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace, COALESCE(context['version'], 'unknown') AS version_or_default, context['region'] AS region FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, MAX(log_ts) AS last_log_ts, SUM(CASE WHEN level = 'DEBUG' THEN retry_count ELSE 0 END) AS debug_retry_count, PERCENTILE_APPROX(latency_ms, 0.5) AS latency_ms_p50, ROUND(AVG(latency_ms), 2) AS avg_latency_ms FROM flattened_attrs GROUP BY DATE_TRUNC('HOUR', log_ts)
